using PvZCoop;
using System.Globalization;
int tests=0;
void Check(bool condition,string name){if(!condition)throw new Exception(name);tests++;Console.WriteLine("PASS "+name);}
CultureInfo.CurrentCulture=CultureInfo.GetCultureInfo("uk-UA");
Check(ZombieVerification.TryRequest(ZombieVerification.Request(17,42),out int id,out long token)&&id==17&&token==42,"request preserves canonical ID and nonce under local culture");
Check(ZombieVerification.TryReply(ZombieVerification.Reply(17,42,false),out id,out token,out bool live)&&id==17&&token==42&&!live,"host terminal confirmation roundtrip");
Check(ZombieVerification.TryReply(ZombieVerification.Reply(17,42,true),out id,out token,out live)&&live,"host live confirmation roundtrip");
foreach(var text in new[]{"0|1","-1|1","1|0","1|-1","1|1|1","1|NaN","+1|1","1| 1"})Check(!ZombieVerification.TryRequest(text,out _,out _),"invalid request rejected "+text);
foreach(var text in new[]{"1|1|2","1|1|true","1|1|00","0|1|0","1|0|0"})Check(!ZombieVerification.TryReply(text,out _,out _,out _),"invalid response rejected "+text);
var tracker=new ZombieVerificationTracker();
Check(tracker.TryRequest(9,0,out long nonce),"missing actor requests verification");
Check(!tracker.TryRequest(9,1.9,out _),"repeated snapshots do not flood verification requests");
Check(tracker.TryRequest(9,2,out long again)&&again==nonce,"retry after delay keeps request identity");
Check(!tracker.Complete(9,nonce+1),"unsolicited or stale nonce cannot authorize cleanup");
Check(tracker.Complete(9,nonce),"matching host response completes outstanding request");
Check(!tracker.Complete(9,nonce),"duplicate host response cannot complete twice");
Check(tracker.TryRequest(9,2.1,out long newer)&&newer>nonce&&!tracker.Complete(9,nonce),"later verification cannot be completed by old response");
tracker.Forget(9);Check(!tracker.Complete(9,newer),"retiring a lifetime clears outstanding verification");
Check(tracker.AllowHostRequest(2,9,0)&&!tracker.AllowHostRequest(2,9,.5)&&tracker.AllowHostRequest(2,9,1),"host rate limit independent of client retry payload");
Check(tracker.AllowHostRequest(3,9,.5),"another authenticated player has an independent request limit");
Check(!tracker.AllowHostRequest(1,9,1)&&!tracker.TryRequest(0,1,out _)&&!tracker.TryRequest(9,double.NaN,out _),"invalid player identity and time cannot enter tracker");
Check(ZombieVerification.HostVerdict(10,10,false,false,false,false)==null,"never-issued ID does not get death confirmation");
Check(ZombieVerification.HostVerdict(9,10,false,true,false,false)==null,"zero HP alone is not a native death certificate");
Check(ZombieVerification.HostVerdict(9,10,false,true,false,true)==true,"living canonical registry entry is confirmed alive");
Check(ZombieVerification.HostVerdict(9,10,true,true,false,true)==false,"terminal lifetime cannot become alive from stale positive HP");
Check(ZombieVerification.HostVerdict(9,10,false,false,false,false)==false,"issued lifetime absent from host registry is confirmed gone");
Check(ZombieVerification.HostVerdict(9,10,false,true,true,true)==false,"native dying status is authoritative despite positive HP");
tracker.Reset();Check(tracker.TryRequest(9,0,out long reset)&&reset==1,"round reset clears pending nonce and limiter history");
Check(!ZombieVerification.NativeTerminal(true,false),"existing zero-HP/nonterminal actor is not retired by snapshot or Charred");
Check(ZombieVerification.NativeTerminal(true,true)&&ZombieVerification.NativeTerminal(false,false),"native Dying or disappearance confirms terminal state");
Check(ZombieVerification.FreshSnapshot(1,float.NegativeInfinity),"first finite snapshot is accepted");
Check(!ZombieVerification.FreshSnapshot(1,1)&&!ZombieVerification.FreshSnapshot(.5f,1),"duplicate and older snapshots cannot advance missing counters");
Check(!ZombieVerification.FreshSnapshot(float.NaN,0)&&!ZombieVerification.FreshSnapshot(float.PositiveInfinity,0),"nonfinite snapshots rejected");
Console.WriteLine("COMPLETE "+tests+" zombie verification assertions");
